import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

function App() {
  const API_KEY = "BURAYA_GOOGLE_API_KEY_YAPISTIR"; 

  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [seciliMekan, setSeciliMekan] = useState(null); 
  const [aktifResimIndex, setAktifResimIndex] = useState(0);

  // --- 1. VERİLERİ ÇEKME ---
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => {
        console.log("GELEN VERİLER:", data); // Konsola yazdır
        setMekanlar(Array.isArray(data) ? data : []);
      })
      .catch(err => alert("BACKEND BAĞLANTISI YOK! server.js çalışıyor mu?"));
  }, []);

  // --- 2. TANI KOYUCU BUTON FONKSİYONU ---
  const favoriEkleCikar = (mekan) => {
    // BU UYARI ÇIKMAZSA BUTON BOZUK DEMEKTİR
    alert("BUTONA BASILDI: " + mekan.ad); 

    setFavoriler((prev) => {
      const varMi = prev.some(item => item.id == mekan.id);
      if (varMi) {
        return prev.filter(item => item.id != mekan.id);
      } else {
        // Süre bilgisini sayıya çevir
        let sure = parseInt(mekan.sure);
        if (isNaN(sure)) sure = 0; 
        return [...prev, { ...mekan, sure: sure }];
      }
    });
  };

  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);

  return (
    <div style={{padding: '20px', fontFamily: 'Arial'}}>
      {/* BAŞLIK VE SAYAÇ */}
      <div style={{textAlign: 'center', marginBottom: '20px'}}>
        <h1 style={{color: '#1a4d6e'}}>Antalya Rota Asistanı</h1>
        <div style={{background: '#1a4d6e', color: 'white', padding: '10px', borderRadius: '10px', display: 'inline-block'}}>
           Rotam: {favoriler.length} Yer | Toplam: {toplamSure} dk
        </div>
      </div>

      {/* KARTLAR */}
      <div style={{display: 'flex', flexWrap: 'wrap', gap: '20px', justifyContent: 'center'}}>
        {mekanlar.map(m => {
          const seciliMi = favoriler.some(f => f.id == m.id);
          const resim = (m.resimler && m.resimler[0]) ? m.resimler[0] : (m.resim || "https://via.placeholder.com/150");

          return (
            <div key={m.id} style={{border: '1px solid #ddd', borderRadius: '10px', width: '250px', overflow: 'hidden', background: 'white'}}>
              {/* Resim Kısmı */}
              <img src={resim} alt={m.ad} style={{width: '100%', height: '150px', objectFit: 'cover'}} 
                   onClick={() => { setSeciliMekan(m); setAktifResimIndex(0); }} 
              />

              <div style={{padding: '15px'}}>
                <h3>{m.ad}</h3>
                <p>{m.bolge} - {m.sure} dk</p>

                {/* --- TEST BUTONU --- */}
                <button 
                  onClick={() => favoriEkleCikar(m)}
                  style={{
                    width: '100%', padding: '10px', 
                    background: seciliMi ? '#ffcccc' : '#ccffcc', 
                    border: '1px solid #999', cursor: 'pointer', fontWeight: 'bold'
                  }}
                >
                  {seciliMi ? 'ÇIKAR' : 'EKLE'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* DETAY MODALI */}
      {seciliMekan && (
        <div style={{position:'fixed', top:0, left:0, right:0, bottom:0, background:'rgba(0,0,0,0.8)', display:'flex', alignItems:'center', justifyContent:'center'}}
             onClick={() => setSeciliMekan(null)}>
          <div style={{background:'white', padding:'20px', borderRadius:'10px', maxWidth:'500px'}} onClick={e => e.stopPropagation()}>
            <img src={seciliMekan.resimler ? seciliMekan.resimler[aktifResimIndex] : seciliMekan.resim} style={{width:'100%', height:'250px', objectFit:'cover'}} />
            {/* Küçük Resimler */}
            <div style={{display:'flex', gap:'5px', marginTop:'10px'}}>
               {seciliMekan.resimler && seciliMekan.resimler.map((r, i) => (
                 <img key={i} src={r} style={{width:'50px', height:'50px', border: i===aktifResimIndex ? '2px solid blue' : 'none'}} onClick={()=>setAktifResimIndex(i)}/>
               ))}
            </div>
            <h2>{seciliMekan.ad}</h2>
            <button onClick={() => setSeciliMekan(null)}>Kapat</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
